:root {
  --cave-bg: #1a1410;
  --cave-surface: #231e18;
  --cave-border: #3d3326;
  --cave-accent: #c8820a;
  --cave-accent-dim: #7a4f08;
  --cave-gold: #e8b84b;
  --cave-text: #e8dfd0;
  --cave-muted: #9a8f7e;
  --cave-high: #d94f3d;
  --cave-med: #e89a2a;
  --cave-low: #5aab6e;
  --cave-blue: #4a8fbe;
  --cave-crystal: #7ec8c8;
}

.cave-log {
  background-color: var(--cave-bg);
  border: 2px solid var(--cave-border);
  border-radius: 10px;
  width: 480px;
  padding: 0;
  overflow: hidden;
  color: var(--cave-text);
}

.log-header {
  background-color: var(--cave-surface);
  border-bottom: 2px solid var(--cave-border);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 12px 16px;
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--cave-accent);
}

.cave-name {
  font-size: 20px;
  font-weight: 800;
  color: var(--cave-gold);
  margin: 0;
  line-height: 1.1;
}

.cave-location {
  font-size: 11px;
  color: var(--cave-muted);
  margin: 0;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}

.difficulty-badge {
  background-color: var(--cave-high);
  color: var(--cave-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.5px;
  padding: 3px 8px;
  border-radius: 4px;
}

.log-id {
  font-size: 11px;
  color: var(--cave-muted);
  font-weight: 600;
  letter-spacing: 1px;
}

.stats-row {
  display: flex;
  border-bottom: 1px solid var(--cave-border);
}

.stat-block {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px;
  border-right: 1px solid var(--cave-border);
  gap: 2px;
}

.stat-block:last-child {
  border-right: none;
}

.stat-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--cave-gold);
  line-height: 1;
}

.stat-unit {
  font-size: 12px;
  font-weight: 600;
  color: var(--cave-accent);
}

.stat-label {
  font-size: 10px;
  color: var(--cave-muted);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.main-grid {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0;
  border-bottom: 1px solid var(--cave-border);
}

.passage-map {
  padding: 12px 14px;
  border-right: 1px solid var(--cave-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.map-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--cave-accent);
}

.map-visual {
  display: flex;
  align-items: center;
  gap: 6px;
}

.map-segment {
  font-size: 11px;
  font-weight: 600;
  padding: 5px 8px;
  border-radius: 5px;
  border: 1px solid var(--cave-border);
  color: var(--cave-text);
  white-space: nowrap;
}

.seg-a {
  background-color: var(--cave-accent-dim);
  border-color: var(--cave-accent);
}

.seg-b {
  background-color: var(--cave-blue);
  border-color: var(--cave-blue);
  color: var(--cave-bg);
  font-weight: 700;
}

.seg-c {
  background-color: var(--cave-surface);
  border-color: var(--cave-crystal);
  color: var(--cave-crystal);
}

.map-arrow {
  font-size: 10px;
  color: var(--cave-muted);
}

.depth-bar {
  position: relative;
  background-color: var(--cave-surface);
  border: 1px solid var(--cave-border);
  border-radius: 4px;
  height: 18px;
  overflow: hidden;
}

.depth-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 68%;
  background-color: var(--cave-accent-dim);
  border-radius: 4px 0 0 4px;
}

.depth-pct {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 10px;
  font-weight: 700;
  color: var(--cave-gold);
  letter-spacing: 0.5px;
}

.hazard-panel {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 120px;
}

.panel-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--cave-accent);
}

.hazard-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.hazard-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--cave-text);
}

.hazard-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.hazard-high .hazard-dot {
  background-color: var(--cave-high);
}

.hazard-med .hazard-dot {
  background-color: var(--cave-med);
}

.hazard-low .hazard-dot {
  background-color: var(--cave-low);
}

.log-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
  background-color: var(--cave-surface);
}

.explorer-info {
  display: flex;
  align-items: center;
  gap: 10px;
}

.explorer-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background-color: var(--cave-accent-dim);
  border: 2px solid var(--cave-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 800;
  color: var(--cave-gold);
}

.explorer-details {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.explorer-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--cave-text);
}

.explorer-role {
  font-size: 10px;
  color: var(--cave-muted);
  letter-spacing: 0.5px;
}

.footer-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
}

.meta-date {
  font-size: 11px;
  color: var(--cave-muted);
  font-weight: 600;
}

.status-pill {
  background-color: var(--cave-accent-dim);
  border: 1px solid var(--cave-accent);
  color: var(--cave-gold);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.5px;
  padding: 3px 9px;
  border-radius: 20px;
}
